(()=>{const q=document.querySelector('#condition-search');if(!q)return;const groups=[...document.querySelectorAll('.topic')],buttons=[...document.querySelectorAll('.filters button')],media=matchMedia('(max-width:700px)');let role='Все темы';const norm=s=>s.toLocaleLowerCase('ru').replaceAll('ё','е').trim();if(media.matches)groups.forEach(g=>g.open=false);function filter(){let n=0;const words=norm(q.value).split(/\s+/).filter(Boolean);groups.forEach(g=>{let count=0;g.querySelectorAll('.items a').forEach(a=>{a.hidden=!(words.every(w=>norm(a.dataset.search).includes(w))&&(role==='Все темы'||JSON.parse(a.dataset.roles).includes(role)));if(!a.hidden)count++});g.hidden=!count;if(words.length||role!=='Все темы')g.open=true;else g.open=!media.matches;n+=count});document.querySelector('.empty-results').hidden=n>0;document.querySelector('.resultnote').textContent=words.length||role!=='Все темы'?'Найдено тем: '+n:'Выберите тему, чтобы узнать о диагностике и подходах к лечению.'}q.addEventListener('input',filter);buttons.forEach(b=>b.addEventListener('click',()=>{role=b.textContent;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));filter()}));document.querySelectorAll('.examples button').forEach(b=>b.addEventListener('click',()=>{role='Все темы';buttons.forEach(x=>x.setAttribute('aria-pressed',String(x.textContent===role)));q.value=b.textContent;filter();q.focus()}));})();